/* 		Exercise 6: Destructor Demonstration		Practice Problem: Create a simple class, e.g., Resource, with a private member std::string id which models acquiring and releasing a resource. Implement a constructor that prints “Resource [ID] acquired” and a destructor that prints “Resource [ID] released”. Use a local object inside a function to clearly show when the destructor is called.		*/#include<iostream>class Resource{	private:	std::string id;		public:	Resource(std::string name):id(name){		std::cout << "Resource : " << id << "Acquiring (constructor) " << std::endl;	}			~Resource(){		std::cout << "Resource : " << id << "Release (Destructor) " << std:: endl;	}};void scopeTest(){	std::cout << "Entering the scopeTest " << std::endl;	Resource localRes("Local A ");	std::cout << "--- Scope Exit ---- " << std::endl;}int main(void){	std::cout << "--- Starting main ---" << std::endl;	Resource mainRes("Local B ");		scopeTest();		std::cout << "--- End main --- " << std::endl;	return 0;}